import{_ as n,o as i,c as a,a3 as l}from"./chunks/framework.B9qR_F1m.js";const c=JSON.parse('{"title":"Checklisten","description":"","frontmatter":{},"headers":[],"relativePath":"ablaeufe/checklisten.md","filePath":"ablaeufe/checklisten.md"}'),r={name:"ablaeufe/checklisten.md"};function s(t,e,h,d,u,o){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="checklisten" tabindex="-1">Checklisten <a class="header-anchor" href="#checklisten" aria-label="Permalink to &quot;Checklisten&quot;">​</a></h1><p>Zum Abhaken, Schritt für Schritt. Das Beispiel ist die Mission <strong>Operation Desert Veil</strong>: ELI 1 (zwei F-16, DEAD gegen die SA-3 bei Palmyra) und ROMAN 1 (zwei F-16, TARCAP), dazu ein Tanker und ein AWACS. H-Hour ist 08:35 L.</p><p>Wer zum ersten Mal plant, liest dazu die Abläufe <a href="./designer">als Mission Designer</a> und <a href="./pilot">als Pilot</a>.</p><h2 id="mission-designer" tabindex="-1">Mission Designer <a class="header-anchor" href="#mission-designer" aria-label="Permalink to &quot;Mission Designer&quot;">​</a></h2><h3 id="phase-1-·-mission-bauen-im-mission-editor" tabindex="-1">Phase 1 · Mission bauen (im Mission Editor) <a class="header-anchor" href="#phase-1-·-mission-bauen-im-mission-editor" aria-label="Permalink to &quot;Phase 1 · Mission bauen (im Mission Editor)&quot;">​</a></h3><div class="checkliste"><ul><li>Client-Flights angelegt, mit Flugzeugtyp, Startplatz und Route. <em>Beispiel: ELI 1 und ROMAN 1 als Client, je zwei F-16C.</em></li><li>Jeder Flight hat eine <strong>eigene Gruppenfrequenz</strong>, damit sich die Flights nicht gegenseitig hören. <em>ELI 1 auf 131.000, ROMAN 1 auf 131.500.</em> Geht auch in Shardwing: <a href="/bereiche/flights#units-funk">Units &amp; Funk</a> oder <strong>Frequenzen verteilen</strong>.</li><li>Tanker und AWACS mit Callsign, Frequenz und TACAN.</li><li>Gegner und SAM-Stellungen gesetzt. Die Namen müssen nicht ordentlich sein, das macht später das IADS-Werkzeug.</li><li>Datum, Startzeit und Wetter eingestellt.</li><li>Missionstitel und Briefing-Texte im ME eingetragen. Der Titel steht auf der Anmeldeseite und auf den Kneeboards.</li></ul></div><h3 id="phase-2-·-offnen-und-uberblick" tabindex="-1">Phase 2 · Öffnen und Überblick <a class="header-anchor" href="#phase-2-·-offnen-und-uberblick" aria-label="Permalink to &quot;Phase 2 · Öffnen und Überblick&quot;">​</a></h3><div class="checkliste"><ul><li>Mission in Shardwing öffnen.</li><li>In der <a href="/bereiche/uebersicht">Übersicht</a> die <strong>Prüfungen</strong> jedes Flights lesen und Warnungen beheben oder bewusst stehen lassen.</li><li>Unter <a href="/bereiche/uebersicht#callsigns-aufgaben">Callsigns &amp; Aufgaben</a> jedem Flight Callsign und Aufgabe geben. <em>„Blue FIGHTER Client #1“ heißt dann ELI 1, Aufgabe DEAD.</em></li></ul></div><h3 id="phase-3-·-lage-intel-und-iads" tabindex="-1">Phase 3 · Lage: Intel und IADS <a class="header-anchor" href="#phase-3-·-lage-intel-und-iads" aria-label="Permalink to &quot;Phase 3 · Lage: Intel und IADS&quot;">​</a></h3><div class="checkliste"><ul><li><a href="/bereiche/iads">IADS</a>: Stellungen nach Konvention benennen und das Netz verbinden, falls die Mission ein IADS-Skript nutzt.</li><li><a href="/bereiche/intel">Intel</a>: Bedrohungen freigeben, die die Piloten kennen sollen. Alles andere bleibt verborgen (keine God-View). <em>Beispiel: zwölf Stellungen für alle freigegeben, die übrigen bleiben eine Überraschung.</em></li><li>Bei wichtigen Bedrohungen „Auf der F10-Karte zeigen“ anhaken, falls sie auch im Spiel auf der Karte stehen sollen.</li><li><a href="/bereiche/zeichnungen">Zeichnungen</a>: FLOT, CAP-Stationen, Tanker-Track, Kill Box. <em>CAP SOUTH für ROMAN, AR MAIN für den Tanker, eine Kill Box um das Ziel.</em></li></ul></div><h3 id="phase-4-·-timing-und-funk" tabindex="-1">Phase 4 · Timing und Funk <a class="header-anchor" href="#phase-4-·-timing-und-funk" aria-label="Permalink to &quot;Phase 4 · Timing und Funk&quot;">​</a></h3><div class="checkliste"><ul><li><a href="/bereiche/timing">Timing</a>: <strong>H-Hour</strong> setzen. <em>08:35 L.</em></li><li>Jedem Flight seinen Auftrag geben: TOT-Fenster, Vul-Zeit oder SEAD/DEAD-Fenster, dazu Push-Zeit, Push-Punkt und Ziel-Punkt. <em>ELI 1: DEAD von H bis H+20, Push H−25 an STPT 5. ROMAN 1: TARCAP ab H−5, Push H−30.</em></li><li>Treffen sich Flights, in den <a href="/bereiche/zeichnungen#planungspunkte">Zeichnungen</a> einen Planungspunkt (RV, Marshal, Holding …) setzen, die Flights eintragen, Zeiten staffeln und Bänder stapeln.</li><li>Gleiche Rahmen für mehrere Flights einmal anlegen und mit <strong>Übertragen auf …</strong> verteilen.</li><li>Tanker-Slots verteilen. Die Matrix zeigt Überschneidungen.</li><li>In der Sync-Matrix prüfen: Kommt jeder Flight laut Route rechtzeitig an? Wann muss er anlassen?</li><li><a href="/bereiche/kneeboards#comm-plan">Comm Plan</a> anlegen: Stationen mit Frequenzen und Preset-Kanäle.</li></ul></div><h3 id="phase-5-·-flights-vorbereiten" tabindex="-1">Phase 5 · Flights vorbereiten <a class="header-anchor" href="#phase-5-·-flights-vorbereiten" aria-label="Permalink to &quot;Phase 5 · Flights vorbereiten&quot;">​</a></h3><p>Für jeden Flight im Bereich <a href="/bereiche/flights">Flights</a>:</p><div class="checkliste"><ul><li><a href="/bereiche/beladung">Beladung</a> passend zum Auftrag. <em>ELI 1: CBU-105 und HARM, ROMAN 1: Luft-Luft.</em></li><li><a href="/bereiche/dtc">DTC</a>: Cartridge <strong>Neu aus Route</strong>. Sie bringt Steerpoints, Funk und die freigegebenen Bedrohungen mit.</li><li>Im Reiter <strong>Units &amp; Funk</strong> den Comm Plan übernehmen, falls er noch abweicht.</li><li><a href="/bereiche/lineup-card">Lineup Card</a>: Joker und Bingo eintragen.</li></ul></div><p>Dürfen die Flight Leads selbst planen, reicht ein grober Stand. Den Rest erledigen sie.</p><h3 id="phase-6-·-kneeboards" tabindex="-1">Phase 6 · Kneeboards <a class="header-anchor" href="#phase-6-·-kneeboards" aria-label="Permalink to &quot;Phase 6 · Kneeboards&quot;">​</a></h3><div class="checkliste"><ul><li><a href="/bereiche/kneeboards">Kneeboards</a> für das ganze Paket: Deckblatt, Auftrag, Wetter, Paket-Tabelle, Kartenausschnitte, Abnormals.</li><li>Die Comm Card ist auf der Lineup Card jedes Flights schon dabei.</li><li>Über das <strong>Rollen-Menü</strong> oben rechts als Lead und als Wingman draufschauen: Fehlt etwas oder verrät eine Seite zu viel? (<a href="/gemeinsam/rollen#ansicht-als">Ansicht als …</a>)</li></ul></div><h3 id="phase-7-·-teilen-wenn-die-flights-selbst-planen" tabindex="-1">Phase 7 · Teilen (wenn die Flights selbst planen) <a class="header-anchor" href="#phase-7-·-teilen-wenn-die-flights-selbst-planen" aria-label="Permalink to &quot;Phase 7 · Teilen (wenn die Flights selbst planen)&quot;">​</a></h3><div class="checkliste"><ul><li><a href="/gemeinsam/teilen">Teilen</a>: Mission auf den Server legen.</li><li><a href="/gemeinsam/rollen#freigaben">Freigaben</a> prüfen: Was darf der Lead ändern, was der Wingman?</li><li>Phase auf <strong>Planung</strong> stellen.</li><li>Link zur <strong>Anmeldeseite</strong> an die Piloten schicken, z. B. im Discord. Den <strong>Designer-Link</strong> für dich behalten.</li><li>Wenn „Selbst prüfen“ an ist: Einreichungen annehmen oder ablehnen.</li></ul></div><h3 id="phase-8-·-einfrieren-und-ausliefern" tabindex="-1">Phase 8 · Einfrieren und ausliefern <a class="header-anchor" href="#phase-8-·-einfrieren-und-ausliefern" aria-label="Permalink to &quot;Phase 8 · Einfrieren und ausliefern&quot;">​</a></h3><div class="checkliste"><ul><li>Phase auf <strong>Eingefroren</strong> stellen, sobald die Planung steht.</li><li>Noch einmal die Prüfungen in der Übersicht und die Sync-Matrix ansehen.</li><li><a href="/dcs/speichern">Speichern</a>: Die .miz enthält jetzt Cartridges, Kneeboards, Zeichnungen und Beladung. Beim Teilen: <strong>Aktuelle .miz</strong> herunterladen.</li><li>Mission auf den DCS-Server legen.</li><li>Wer will, bekommt zusätzlich PDF oder Kneeboard-ZIP aus der Übersicht.</li></ul></div><h2 id="flight-lead" tabindex="-1">Flight Lead <a class="header-anchor" href="#flight-lead" aria-label="Permalink to &quot;Flight Lead&quot;">​</a></h2><p>Du hast den Link zur Anmeldeseite bekommen.</p><div class="checkliste"><ul><li>Link öffnen, den Platz als Flight Lead wählen, Namen eintragen, <strong>übernehmen</strong>.</li><li>Den <strong>persönlichen Link</strong> als Lesezeichen speichern.</li><li>Auftrag lesen: In der Übersicht und im <a href="/bereiche/timing">Timing</a> stehen Push-Zeit, TOT oder Vul und der Tanker-Slot. <em>ELI 1: Push 08:10 L an STPT 5, DEAD 08:35 bis 08:55 L.</em></li><li>Route im <a href="/bereiche/dtc">DTC</a> prüfen und anpassen.</li><li>Im <a href="/bereiche/dtc#tos-rechner">TOS-Rechner</a> jeder Sollzeit den passenden Steerpoint zuordnen. Halten (z. B. am Tanker) eintragen, dann <strong>TOS übernehmen</strong>.</li><li><a href="/bereiche/beladung">Beladung</a> wählen, wenn sie freigegeben ist.</li><li><a href="/bereiche/angriff">Angriff</a> planen, wenn ihr ein Bodenziel habt. <em>ELI 1: CBU-Toss auf die SA-3.</em></li><li><a href="/bereiche/lineup-card">Lineup Card</a>: Joker, Bingo und Hinweise für dein Element.</li><li>In der Übersicht die <strong>Prüfungen</strong> deines Flights lesen. „Keine Auffälligkeiten“ ist das Ziel.</li><li>Deinen Wingman informieren, wenn sich etwas Wichtiges geändert hat.</li></ul></div><h2 id="wingman" tabindex="-1">Wingman <a class="header-anchor" href="#wingman" aria-label="Permalink to &quot;Wingman&quot;">​</a></h2><div class="checkliste"><ul><li>Link öffnen, den Platz als Wingman wählen, Namen eintragen, <strong>übernehmen</strong>.</li><li>Den <strong>persönlichen Link</strong> als Lesezeichen speichern.</li><li>Route, Timing und Lineup Card ansehen. Ändern macht dein Lead.</li><li>Eigene <strong>CMDS-Programme</strong> und <strong>Farben</strong> einstellen, wenn du willst. Sie gelten nur für deinen Jet.</li><li>Für unterwegs PDF oder Kneeboard-ZIP aus der Übersicht holen.</li></ul></div><h2 id="im-jet-alle" tabindex="-1">Im Jet (alle) <a class="header-anchor" href="#im-jet-alle" aria-label="Permalink to &quot;Im Jet (alle)&quot;">​</a></h2><div class="checkliste"><ul><li>Cartridge laden: auf der <strong>DTE-Seite</strong>, oder sie lädt mit AutoLoad von selbst.</li><li>Funk prüfen: Die Kanäle stehen wie auf der Comm Card.</li><li>Kneeboard mit <kbd>K</kbd> öffnen: Lineup Card, Comm Card, Routenkarte, Attack Card.</li><li>Steerpoints und TOS im DED kurz durchblättern.</li></ul></div><p>Mehr dazu: <a href="/dcs/cockpit">Im Cockpit</a>.</p>',30)])])}const f=n(r,[["render",s]]);export{c as __pageData,f as default};
